 for(const value of durationOptions()){
  const item=document.createElement('button');item.type='button';item.dataset.restDuration=value.duration;item.dataset.restDots=String(value.dots);item.setAttribute('aria-label',t('Rest')+' '+value.duration+' '+('·'.repeat(value.dots)));item.innerHTML=NotationSymbols.rest(value.duration)+'<span>'+('·'.repeat(value.dots))+'</span>';
  if(value.duration===(state.lastRestDuration||state.choice.duration)&&value.dots===(state.lastRestDots||0))item.className='active';
  item.onclick=()=>{close();if(state.route!=='editor'||state.sheet!==sheet||!sheet.editable)return;state.lastRestDuration=value.duration;state.lastRestDots=value.dots;insert('B4','',true,{duration:value.duration,dots:value.dots});};options.append(item);
 }
 dialog.append(options);const cancel=document.createElement('button');cancel.type='button';cancel.className='rest-duration-cancel';cancel.textContent=t('Cancel');cancel.onclick=close;dialog.append(cancel);dialog.addEventListener('cancel',event=>{event.preventDefault();close();});document.body.append(dialog);dialog.showModal();const active=dialog.querySelector('.active');if(active){active.focus();active.scrollIntoView({block:'nearest'});}
